class Worker
{
    private bool _stop;              // a plain field

    public void Run()
    {
        long n = 0;
        while (!_stop) n++;          // the JIT may read _stop only once
    }

    public void Stop() => _stop = true;
}

cards/2/code:
var w = new Worker();
var t = new Thread(w.Run);
t.Start();
Thread.Sleep(1000);
w.Stop();
t.Join();
Console.WriteLine("done");

